+func TestCommitPipelineBatchDurableOnSyncError(t *testing.T) {
+	defer leaktest.AfterTest(t)()
+	var logSeqNum base.AtomicSeqNum
+	var visibleSeqNum base.AtomicSeqNum
+	injectedErr := errors.New("injected sync error")
+	var mu sync.Mutex
+	var durableInfo BatchDurableInfo
+	env := commitEnv{
+		logSeqNum:     &logSeqNum,
+		visibleSeqNum: &visibleSeqNum,
+		apply: func(b *Batch, mem *memTable) error {
+			return nil
+		},
+		write: func(b *Batch, wg *sync.WaitGroup, err *error) (*memTable, error) {
+			if wg != nil {
+				*err = injectedErr
+				wg.Done()
+			}
+			return nil, nil
+		},
+		batchDurable: func(b *Batch) {
+			mu.Lock()
+			defer mu.Unlock()
+			durableInfo = BatchDurableInfo{
+				JobID:         int(b.durableJobID),
+				SeqNum:        b.durableSeqNum,
+				Err:           b.commitErr,
+				ApplyDuration: b.applyDuration,
+				SyncDuration:  b.syncDuration,
+				CorrelationID: b.correlationID,
+				BatchSize:     b.batchSize,
+				KeyCount:      b.keyCount,
+			}
+		},
+	}
+	p := newCommitPipeline(env)
+	var b Batch
+	require.NoError(t, b.Set([]byte("a"), []byte("1"), nil))
+	err := p.Commit(&b, true, false)
+	require.Error(t, err)
+	require.Equal(t, injectedErr, err)
+	mu.Lock()
+	defer mu.Unlock()
+	require.Equal(t, injectedErr, durableInfo.Err)
+}
