   220	// Pops all entries up to and including index. The remaining queue is
   221	// [index+1, head).
   222	//
   223	// NB: we could slightly simplify to only have the latest writer be able to
   224	// pop. This would avoid the CAS below, but it seems better to reduce the
   225	// amount of queued work regardless of who has successfully written it.
   226	func (q *recordQueue) pop(index uint32, err error) (numSyncsPopped int) {
   227		now := crtime.NowMono()
   228		var buf [512]poppedEntry
   229		tailEntriesToPop := func() (t uint32, numEntriesToPop int) {
   230			ht := q.headTail.Load()
   231			_, t = unpackHeadTail(ht)
   232			tail := int(t)
   233			numEntriesToPop = int(index) - tail + 1
   234			return t, numEntriesToPop
   235		}
   236		q.consumerMu.Lock()
   237		// numEntriesToPop is a function of index and tail. The value of tail cannot
   238		// change since consumerMu is held.
   239		tail, numEntriesToPop := tailEntriesToPop()
   240		if numEntriesToPop <= 0 {
   241			q.consumerMu.Unlock()
   242			return 0
   243		}
   244		var b []poppedEntry
   245		if numEntriesToPop <= len(buf) {
   246			b = buf[:numEntriesToPop]
   247		} else {
   248			// Do allocation before acquiring the mutex.
   249			b = make([]poppedEntry, numEntriesToPop)
   250		}
   251		q.mu.RLock()
   252		n := len(q.buffer)
   253		for i := 0; i < numEntriesToPop; i++ {
   254			// Grab the popped entries before incrementing tail, since that will
   255			// release those buffer slots to the producer.
   256			idx := (i + int(tail)) % n
   257			b[i] = poppedEntry{
   258				opts:       q.buffer[idx].opts,
   259				refCount:   q.buffer[idx].refCount,
   260				writeStart: q.buffer[idx].writeStart,
   261			}
   262		}
   263		// Since tail cannot change, we don't need to do a compare-and-swap.
   264		q.headTail.Add(uint64(numEntriesToPop))
   265		q.mu.RUnlock()
   266		q.consumerMu.Unlock()
   267		addLatencySample := false
   268		var maxLatency time.Duration
   269		for i := 0; i < numEntriesToPop; i++ {
   270			// Now that we've synced the entry, we can unref it to signal that we
   271			// will not read the written byte slice again.
   272			if b[i].refCount != nil {
   273				b[i].refCount.Unref()
   274			}
   275			if b[i].opts.Done != nil {
   276				numSyncsPopped++
   277				if err != nil {
   278					*b[i].opts.Err = err
   279				}
   280				b[i].opts.Done.Done()
   281				latency := now.Sub(b[i].writeStart)
   282				if !addLatencySample {
   283					addLatencySample = true
   284					maxLatency = latency
   285				} else if maxLatency < latency {
   286					maxLatency = latency
   287				}
   288			}
   289		}
